async function nav(path,width,theme){await p.send('Emulation.setDeviceMetricsOverride',{width,height:900,deviceScaleFactor:1,mobile:width<500});await p.send('Page.navigate',{url:origin+path});await p.wait("!!document.querySelector('main h1')&&!document.querySelector('#prerender-seo')&&!!document.querySelector('button[aria-label*=theme]')");await p.evaluate('document.fonts.ready.then(()=>true)',true);await p.evaluate("[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Reject analytics')?.click();true");await p.evaluate(`if(document.documentElement.classList.contains('light')!==${theme==='light'})[...document.querySelectorAll('button[aria-label*=theme]')].find(b=>b.getClientRects().length).click();true`);await pause(500);assert.equal(await p.evaluate("document.documentElement.classList.contains('light')?'light':'dark'"),theme);}
try{for(const theme of['light','dark'])for(const width of[360,390,768,1280,1920]){
 await nav('/learn',width,theme);const targets=await p.evaluate("[...document.querySelectorAll('main span,main h3')].filter(e=>/^(Step [1-3]|Foundations|Strategy & Analysis|Advanced Practice)$/.test(e.textContent.trim())).map(e=>{const s=getComputedStyle(e),layers=[];for(let x=e;x;x=x.parentElement){const q=getComputedStyle(x);layers.push({background:q.backgroundColor});if(q.backgroundColor.startsWith('rgb('))break;}return{text:e.textContent,color:s.color,layers,y:Math.max(0,scrollY+e.getBoundingClientRect().top-150)}})");assert.equal(targets.length,9);for(const t of targets){let bg=[255,255,255];for(const l of[...t.layers].reverse())bg=over(rgb(l.background),bg);const fg=over(rgb(t.color),bg);t.contrast=ratio(fg,bg);assert.ok(t.contrast>=4.5,'Label contrast '+t.text+' '+t.contrast);}const labelShots=[];for(const i of[0,2]){await p.evaluate(`scrollTo(0,${targets[i].y});true`);await pause(400);const n=`labels-${i}-${width}-${theme}.png`;await p.screenshot(folder+'/'+n);labelShots.push(n);}rows.push({kind:'labels',width,theme,path:'/learn',targets,screenshots:labelShots});
 await nav('/trader/muzh3q',width,theme);await p.wait("!!document.querySelector('button[aria-label=\"Play background music\"]')");for(const position of['top','footer'])for(const hover of[false,true]){await p.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:1,y:110});await p.evaluate(position==='top'?'scrollTo(0,0);true':'scrollTo(0,document.documentElement.scrollHeight);true');const box=await p.evaluate("(()=>{const r=document.querySelector('button[aria-label=\"Play background music\"]').getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()");if(hover)await p.send('Input.dispatchMouseEvent',{type:'mouseMoved',...box});await pause(500);const info=await p.evaluate("(()=>{const b=document.querySelector('button[aria-label=\"Play background music\"]'),s=getComputedStyle(b),r=b.getBoundingClientRect();return{color:s.color,background:s.backgroundColor,border:s.borderColor,box:{x:r.x,y:r.y,width:r.width,height:r.height},name:b.getAttribute('aria-label'),overflow:document.documentElement.scrollWidth>innerWidth+1}})()");const bg=over(rgb(info.background),[theme==='light'?247:10,theme==='light'?247:10,theme==='light'?247:10]);const backgrounds=theme==='light'?[bg]:[over(rgb(info.background),[0,0,0]),over(rgb(info.background),[20,20,20])];const contrasts=backgrounds.map(b=>ratio(over(rgb(info.color),b),b));assert.ok(Math.min(...contrasts)>=3,'Icon contrast');assert.equal(info.name,'Play background music');assert.equal(info.overflow,false);const n=`audio-${position}-${hover?'hover':'rest'}-${width}-${theme}.png`;await p.screenshot(folder+'/'+n);rows.push({kind:'audio',path:'/trader/muzh3q',width,theme,position,hover,...info,contrast:Math.min(...contrasts),contrastScope:theme==='light'?'Opaque light backing':'Conservative dark backing range0..20; no arbitrary bright-overlay claim',screenshot:n});}
}assert.deepEqual(errors,[]);}catch(e){failure=e.message;throw e;}finally{writeFileSync(root+'CONTRAST-SURFACES-'+stage.toUpperCase()+'-20261030.json',JSON.stringify({checkedAt:new Date().toISOString(),sha,origin,outcome:failure?'FAIL':'PASS',failure,rows,runtimeErrors:errors,blocked,scope:'Three Learning Path labels/step foregrounds and inactive floating audio control; five widths, two real themes, top/black footer and rest/hover. No playback click, active state, account, orders, progress or consent implementation change. Requires personal screenshot review; not full accessibility certification.'},null,2)+'\n');await p.close();}
